def transform(g):
    from collections import Counter
    n,m=len(g),len(g[0])
    brk=Counter()
    for i in range(n):
        for j in range(m):
            if g[i][j]!=g[n-1-i][m-1-j]:
                brk[g[i][j]]+=1; brk[g[n-1-i][m-1-j]]+=1
    noise=brk.most_common(1)[0][0]
    c=Counter(x for r in g for x in r); bg=c.most_common(1)[0][0]
    return [[bg if g[i][j]==noise and g[n-1-i][m-1-j]==noise else (g[n-1-i][m-1-j] if g[i][j]==noise else g[i][j]) for j in range(m)] for i in range(n)]
